# Encode the four 5x5 panels from the test input and apply the line-partition rule.
P = [(0,2),(1,2),(2,2),(2,3),(2,4)]
marker=(0,4)
from collections import deque
allcells={(r,c) for r in range(5) for c in range(5)}
free=allcells-set(P)
q=deque([marker]); marked={marker}
while q:
    r,c=q.popleft()
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        n=(r+dr,c+dc)
        if n in free and n not in marked:
            marked.add(n); q.append(n)
print('marker-side', sorted(marked), 'size', len(marked))
B=[[5,3,5,3,5],[3,3,5,3,3],[5,5,5,5,5],[3,3,5,3,3],[5,3,5,3,5]]
C=[[7,7,5,7,7],[7,5,5,5,7],[5,5,5,5,5],[7,5,5,5,7],[7,7,5,7,7]]
# Use pattern B on the marker side, C on the other side; both sides touch path, with B priority.
D=[]
for r in range(5):
    row=[]
    for c in range(5):
        pt=(r,c)
        in_B_side = pt in marked or pt in P
        in_C_side = pt not in marked or pt in P
        if in_B_side and B[r][c] != 5: row.append(B[r][c])
        elif in_C_side and C[r][c] != 5: row.append(C[r][c])
        else: row.append(5)
    D.append(row)
print(*D, sep='\n')
